package com.c203.limit.domain.admin.entity;import static org.assertj.core.api.Assertions.*;import java.time.OffsetDateTime;import org.junit.jupiter.api.Test;import com.c203.limit.domain.member.entity.Member;import com.c203.limit.global.exception.*;
class MemberRestrictionTests{@Test void rejectsInvalidPeriod(){var m=Member.createLocal("u@example.com","p","runner",null);var now=OffsetDateTime.now();assertThatThrownBy(()->MemberRestriction.create(m,"LOGIN","POLICY","reason",now,now.minusDays(1),1L)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.getErrorCode()).isEqualTo(ErrorCode.INVALID_RESTRICTION_PERIOD));}@Test void activeRestrictionCanBeReleased(){var m=Member.createLocal("u@example.com","p","runner",null);var now=OffsetDateTime.now();var r=MemberRestriction.create(m,"LOGIN","POLICY","reason",now,now.plusDays(1),1L);r.release(2L,"false positive");assertThat(r.getStatus()).isEqualTo("RELEASED");assertThat(r.getReleasedBy()).isEqualTo(2L);}}
